@keyframes cosmos-sea-twinkle {
  0%, 100% { opacity: 0.1; transform: scale(0.8); }
  50%      { opacity: 0.8; transform: scale(1.2); }
}

/* ── 折叠控件样式 details & summary ── */
.cosmos-sea-details {
  position: relative;
  z-index: 2;
