  box-shadow: inset 0 -10px 20px -10px rgba(100, 180, 255, 0.1);
}

/* ── 字体白光发光效果 ── */
.cosmos-sea-glow {
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.5), 0 0 15px rgba(200, 230, 255, 0.3);
}

/* ── 常显顶部：日期与地点 ── */
.cosmos-sea-top-item {
  display: flex;
