  font-family: Georgia, "Songti SC", "Noto Serif SC", serif;
  color: #ffffff;
}

/* ── 主面板：水中百合·磨砂玻璃水蓝 ── */
.lily-panel {
  position: relative;
  background: rgba(20, 100, 140, 0.52);
  backdrop-filter: blur(22px) saturate(180%);
  -webkit-backdrop-filter: blur(22px) saturate(180%);
  border-radius: 18px;
  width: 100%;
  max-width: 500px;
  outline: 1px solid rgba(255, 255, 255, 0.32);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.10),
    inset 0 1px 0 rgba(255, 255, 255, 0.45),
    inset 0 -1px 0 rgba(100, 200, 240, 0.2),
    0 20px 60px rgba(20, 80, 120, 0.55);
  overflow: hidden;
  animation: lily-fadeIn 1.2s ease-out both;
}

@keyframes lily-fadeIn {
  from { opacity: 0; transform: translateY(18px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* ── 水面波纹光影层 ── */
.lily-water-surface {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  overflow: hidden;
}

/* 大波纹涟漪 */
.lily-ripple {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(120, 180, 255, 0.1);
  animation: lily-ripple-expand 6s ease-out infinite;
}
.lily-ripple:nth-child(1) { width: 120px; height: 60px; left: 10%; top: 20%; animation-delay: 0s; }
.lily-ripple:nth-child(2) { width: 180px; height: 80px; left: 55%; top: 50%; animation-delay: 2s; animation-duration: 7s; }
.lily-ripple:nth-child(3) { width: 90px;  height: 40px; left: 30%; top: 70%; animation-delay: 4s; animation-duration: 5s; }

@keyframes lily-ripple-expand {
  0%   { transform: scale(0.6); opacity: 0.4; }
  60%  { opacity: 0.15; }
  100% { transform: scale(2.4); opacity: 0; }
}

/* 水面折射高光条纹 */
.lily-caustic {
  position: absolute;
  width: 2px;
  border-radius: 2px;
  background: linear-gradient(180deg, transparent, rgba(160, 210, 255, 0.22), transparent);
  animation: lily-caustic-drift 5s ease-in-out infinite alternate;
}
.lily-caustic:nth-child(4)  { height: 60px; left: 18%; top: 10%; animation-delay: 0s; }
.lily-caustic:nth-child(5)  { height: 40px; left: 45%; top: 30%; animation-delay: 1.3s; width: 1.5px; }
.lily-caustic:nth-child(6)  { height: 80px; left: 72%; top: 5%;  animation-delay: 2.6s; }
.lily-caustic:nth-child(7)  { height: 50px; left: 60%; top: 60%; animation-delay: 0.8s; width: 1px; }
.lily-caustic:nth-child(8)  { height: 35px; left: 85%; top: 40%; animation-delay: 3.1s; }
.lily-caustic:nth-child(9)  { height: 70px; left: 28%; top: 55%; animation-delay: 1.9s; width: 1px; }

@keyframes lily-caustic-drift {
  0%   { transform: translateX(-4px) scaleY(0.8); opacity: 0.3; }
  100% { transform: translateX(4px)  scaleY(1.2); opacity: 0.7; }
}

/* 水中折光闪点 */
.lily-sparkle {
  position: absolute;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 0 6px 2px rgba(130, 190, 255, 0.7);
  animation: lily-sparkle-blink 3s ease-in-out infinite;
}

@keyframes lily-sparkle-blink {
  0%, 100% { opacity: 0.05; transform: scale(0.5); }
  50%      { opacity: 0.85; transform: scale(1.3); }
}

/* 漂浮花瓣轮廓（纯CSS百合花瓣剪影） */
.lily-petal {
  position: absolute;
  border-radius: 70% 30% 70% 30% / 50% 70% 30% 50%;
  background: rgba(200, 225, 255, 0.04);
  border: 1px solid rgba(150, 200, 255, 0.14);
  animation: lily-petal-float 9s ease-in-out infinite alternate;
}

@keyframes lily-petal-float {
  0%   { transform: rotate(0deg) translateY(0px); }
  100% { transform: rotate(8deg) translateY(-6px); }
}

/* ── 折叠控件样式 details & summary ── */
.lily-details {
  position: relative;
  z-index: 2;
}

.lily-details > summary {
  list-style: none;
  cursor: pointer;
  outline: none;
  padding: 18px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(255, 255, 255, 0.02);
  border-bottom: 1px solid transparent;
  transition: all 0.4s ease;
  backdrop-filter: blur(2px);
}
.lily-details > summary::-webkit-details-marker { display: none; }

.lily-details[open] > summary {
  background: rgba(255, 255, 255, 0.06);
  border-bottom: 1px solid rgba(255, 255, 255, 0.28);
  box-shadow: inset 0 -12px 24px -10px rgba(100, 200, 240, 0.12);
}

/* ── 水光文字发光 ── */
.lily-glow {
  text-shadow:
    0 0 10px rgba(255, 255, 255, 0.55),
    0 0 20px rgba(180, 230, 255, 0.3);
}

/* ── 常显顶部：日期与地点 ── */
.lily-top-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.lily-top-item.right { text-align: right; }

.lily-label {
  font-size: 10px;
  letter-spacing: 4px;
  color: rgba(255, 255, 255, 0.5);
  text-transform: uppercase;
}
.lily-val-main {
  font-size: 15px;
  font-weight: 300;
  letter-spacing: 2px;
  color: rgba(255, 255, 255, 0.95);
}

/* 展开图标 */
.lily-summary-icon::after {
  content: "▼";
  font-size: 10px;
  color: rgba(255, 255, 255, 0.45);
  margin-left: 12px;
  transition: transform 0.3s ease;
  display: inline-block;
}
.lily-details[open] > summary .lily-summary-icon::after {
  transform: rotate(180deg);
  color: rgba(255, 255, 255, 0.95);
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.8);
}

/* ── 展开内容区 ── */
.lily-content {
  padding: 20px 24px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  animation: lily-slideDown 0.4s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes lily-slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* 第一行：年纪 与 倒计时 并排 */
.lily-row-split {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  position: relative;
  overflow: hidden;
}

/* 花瓣透明装饰叠加在行内 */
.lily-row-split::before {
  content: "";
  position: absolute;
  right: -20px;
  top: -20px;
  width: 80px;
  height: 80px;
  border-radius: 70% 30% 60% 40% / 50% 60% 40% 50%;
  background: rgba(150, 200, 255, 0.03);
  border: 1px solid rgba(150, 200, 255, 0.07);
  transform: rotate(-20deg);
}

.lily-split-box {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.lily-split-box.right { text-align: right; }

.lily-val-sub {
  font-size: 14px;
  color: #b8d8ff;
  letter-spacing: 1px;
}

/* 水波分隔线 */
.lily-divider {
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(80, 160, 255, 0.2) 30%,
    rgba(160, 210, 255, 0.38) 50%,
    rgba(80, 160, 255, 0.2) 70%,
    transparent 100%
  );
  margin: 4px 0;
  position: relative;
}

/* 分隔线上的波光亮点 */
.lily-divider::after {
  content: "✦";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-size: 7px;
  color: rgba(140, 200, 255, 0.55);
  line-height: 1;
}

/* 第二行：心声 */
.lily-row-full {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 4px;
}

.lily-quote {
  font-size: 14px;
  font-style: italic;
  color: #b8d4f8;
  line-height: 1.6;
  letter-spacing: 1px;
  position: relative;
  padding-left: 14px;
  border-left: 2px solid rgba(100, 170, 255, 0.45);
}

/* 第三行：状态框 */
.lily-status-box {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 14px;
  background: rgba(80, 140, 255, 0.03);
  border-radius: 8px;
  border: 1px dashed rgba(90, 160, 255, 0.22);
  position: relative;
  overflow: hidden;
}

/* 状态框右下角百合花瓣装饰 */
.lily-status-box::after {
  content: "";
  position: absolute;
  bottom: -10px;
  right: -10px;
  width: 60px;
  height: 80px;
  border-radius: 50% 20% 50% 20% / 70% 50% 70% 30%;
  background: rgba(150, 200, 255, 0.03);
  border: 1px solid rgba(150, 200, 255, 0.08);
  transform: rotate(30deg);
}

.lily-status-text {
  font-size: 13px;
  color: #b8d4f5;
  line-height: 1.65;
}

/* 移动端细调 */
@media (max-width: 400px) {
  .lily-details > summary { padding: 12px 16px; }
  .lily-content { padding: 16px 16px 20px; }
  .lily-val-main { font-size: 13px; }
}
</style>

