@keyframes cosmos-deep-wave{0%{transform:scale(1) translate(0,0);opacity:0.5;}100%{transform:scale(1.05) translate(-8px,12px);opacity:1;}}
@keyframes cosmos-deep-twinkle{0%,100%{opacity:0.1;transform:scale(0.8);}50%{opacity:0.75;transform:scale(1.2);}}

.fold-item{border-radius:16px;overflow:hidden;max-width:650px;margin:10px auto;}
.fold-trigger{
  display:flex;align-items:center;justify-content:space-between;
  padding:14px 22px;cursor:pointer;user-select:none;transition:opacity 0.18s;
  background:linear-gradient(135deg,#050f20 0%,#091828 50%,#040c18 100%);
  border:1px solid rgba(120,190,255,0.14);
  font-family:Georgia,"Songti SC","Noto Serif SC",serif;
}
.fold-trigger:hover{opacity:0.85;}
.fold-title-group{display:flex;flex-direction:column;gap:3px;}
.fold-label{font-size:10px;letter-spacing:4px;text-transform:uppercase;color:rgba(150,200,255,0.52);}
.fold-name{font-size:16px;font-weight:300;letter-spacing:3px;color:#ffffff;text-shadow:0 0 8px rgba(255,255,255,0.38),0 0 16px rgba(150,200,255,0.22);}
.fold-arrow{font-size:10px;color:rgba(150,200,255,0.42);transition:transform 0.3s ease;flex-shrink:0;}
.fold-item.open .fold-arrow{transform:rotate(90deg);}
.fold-body{max-height:0;overflow:hidden;transition:max-height 0.45s cubic-bezier(0.4,0,0.2,1);}
.fold-item.open .fold-body{max-height:5000px;}
.fold-body-inner{animation:cardFadeIn 0.4s ease both;}

.cosmos-deep-panel{position:relative;background:linear-gradient(135deg,#030a14 0%,#0a1b35 50%,#040d1a 100%);border-radius:0 0 16px 16px;width:100%;box-shadow:inset 0 0 40px rgba(100,180,255,0.03);border:1px solid rgba(120,190,255,0.10);border-top:none;overflow:hidden;font-family:Georgia,"Songti SC","Noto Serif SC",serif;color:#ffffff;}
.cosmos-deep-glimmer{position:absolute;inset:0;pointer-events:none;z-index:1;background-image:radial-gradient(circle at 10% 20%,rgba(200,230,255,0.02) 0%,transparent 40%),radial-gradient(circle at 90% 80%,rgba(100,180,255,0.025) 0%,transparent 50%);animation:cosmos-deep-wave 10s infinite alternate ease-in-out;}
.cosmos-deep-star{position:absolute;border-radius:50%;background:#ffffff;box-shadow:0 0 8px rgba(255,255,255,0.7);animation:cosmos-deep-twinkle 4s ease-in-out infinite;}
.cosmos-deep-glow{text-shadow:0 0 8px rgba(255,255,255,0.45),0 0 14px rgba(150,200,255,0.28);}
.cosmos-deep-content{position:relative;z-index:2;padding:22px 24px 30px;display:flex;flex-direction:column;gap:28px;}
.cosmos-deep-section{display:flex;flex-direction:column;gap:14px;}
.cosmos-deep-section-title{font-size:16px;color:#e6f0ff;display:flex;align-items:center;gap:10px;letter-spacing:2px;}
.cosmos-deep-section-title::before{content:"✧";font-size:12px;color:rgba(150,200,255,0.75);}
.cosmos-deep-section-title::after{content:"";flex:1;height:1px;background:linear-gradient(90deg,rgba(150,200,255,0.18),transparent);}
.cosmos-deep-card{background:rgba(0,0,0,0.22);border:1px solid rgba(255,255,255,0.04);border-radius:10px;padding:16px 18px;display:flex;flex-direction:column;gap:9px;}
.cosmos-deep-item-title{font-size:14px;color:#ffffff;border-left:2px solid rgba(150,200,255,0.45);padding-left:10px;letter-spacing:1px;}
.cosmos-deep-text{font-size:13px;color:#b3d1ff;line-height:1.7;text-align:justify;}
.cosmos-deep-text strong{color:#e6f0ff;font-weight:normal;}
.cosmos-deep-highlight{display:inline-block;background:rgba(150,200,255,0.09);padding:2px 6px;border-radius:4px;color:#cce0ff;font-size:12px;margin-top:4px;}
.cosmos-deep-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:13px;}
.cosmos-deep-grid-item{background:rgba(0,0,0,0.14);border-top:1px solid rgba(255,255,255,0.03);padding:11px 13px;border-radius:6px;}
.cosmos-deep-grid-title{font-size:13.5px;color:#ffffff;margin-bottom:5px;display:block;}
</style>

<div class="fold-item" id="fold0">
  <div class="fold-trigger" onclick="document.getElementById('fold0').classList.toggle('open')">
    <div class="fold-title-group">
      <span class="fold-label">Abyssal Observation Records</span>
