<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
</head>
<body>
<style>
*{box-sizing:border-box;margin:0;padding:0;}
body{background:transparent;font-family:Georgia,"Songti SC","Noto Serif SC",serif;}

@keyframes fadeIn{from{opacity:0;transform:translateY(10px);}to{opacity:1;transform:translateY(0);}}
@keyframes npc-wave{0%{transform:scale(1) translate(0,0);opacity:0.6;}100%{transform:scale(1.05) translate(10px,-10px);opacity:1;}}
@keyframes npc-twinkle{0%,100%{opacity:0.1;transform:scale(0.8);}50%{opacity:0.8;transform:scale(1.2);}}
@keyframes musicPulse{0%,100%{box-shadow:0 0 0 0 rgba(100,200,240,0.4);}50%{box-shadow:0 0 0 6px rgba(100,200,240,0);}}
@keyframes barDance{0%,100%{transform:scaleY(0.4);}50%{transform:scaleY(1);}}

.fold-item{
  max-width:500px;margin:10px auto;
  border-radius:18px;overflow:hidden;
  animation:fadeIn 0.8s ease both;
}

/* ── 触发栏 ── */
.fold-trigger{
  display:flex;align-items:center;justify-content:space-between;
  padding:14px 20px;cursor:pointer;user-select:none;
  /* 区别色：偏向青蓝/冰蓝而非深海蓝 */
  background:linear-gradient(135deg,rgba(8,28,52,0.96) 0%,rgba(12,40,72,0.98) 50%,rgba(6,22,44,0.97) 100%);
  border:1px solid rgba(80,200,240,0.22);
  border-bottom:1px solid rgba(80,200,240,0.10);
  transition:opacity 0.18s;
  gap:12px;
}
.fold-trigger:hover{opacity:0.88;}
.fold-left{display:flex;align-items:center;gap:12px;flex:1;min-width:0;}
.fold-title-group{display:flex;flex-direction:column;gap:3px;}
.fold-label{font-size:10px;letter-spacing:4px;text-transform:uppercase;color:rgba(100,220,255,0.45);}
.fold-name{
  font-size:16px;font-weight:300;letter-spacing:3px;color:#ffffff;
  text-shadow:0 0 10px rgba(80,220,255,0.55),0 0 20px rgba(60,180,240,0.25);
}
.fold-arrow{font-size:10px;color:rgba(80,210,255,0.40);transition:transform 0.3s ease;flex-shrink:0;}
.fold-item.open .fold-arrow{transform:rotate(90deg);}

/* ── 音乐按钮 ── */
.music-btn{
  display:flex;align-items:center;gap:7px;
  padding:6px 12px;border-radius:20px;cursor:pointer;
  background:rgba(60,180,240,0.10);
  border:1px solid rgba(80,210,255,0.28);
  color:rgba(140,230,255,0.75);
  font-size:11px;letter-spacing:1.5px;
  font-family:Georgia,"Songti SC",serif;
  transition:all 0.22s;flex-shrink:0;
}
.music-btn:hover{background:rgba(60,180,240,0.18);border-color:rgba(100,220,255,0.45);color:rgba(200,245,255,0.92);}
.music-btn.playing{
  background:rgba(60,180,240,0.18);
  border-color:rgba(100,220,255,0.5);
  color:rgba(200,245,255,0.95);
  animation:musicPulse 1.8s ease-in-out infinite;
}
.music-icon{font-size:12px;line-height:1;}
.music-bars{display:flex;align-items:flex-end;gap:2px;height:12px;}
.music-bars span{
  display:block;width:2px;background:rgba(120,230,255,0.8);border-radius:1px;
  transform:scaleY(0.4);transform-origin:bottom;
}
.music-bars span:nth-child(1){height:8px;animation:barDance 0.6s 0s ease-in-out infinite;}
.music-bars span:nth-child(2){height:12px;animation:barDance 0.6s 0.15s ease-in-out infinite;}
.music-bars span:nth-child(3){height:6px;animation:barDance 0.6s 0.3s ease-in-out infinite;}
.music-bars span:nth-child(4){height:10px;animation:barDance 0.6s 0.1s ease-in-out infinite;}
.music-bars-static{display:flex;align-items:flex-end;gap:2px;height:12px;}
.music-bars-static span{display:block;width:2px;border-radius:1px;background:rgba(120,220,255,0.55);}
.music-bars-static span:nth-child(1){height:6px;}
.music-bars-static span:nth-child(2){height:10px;}
.music-bars-static span:nth-child(3){height:5px;}
.music-bars-static span:nth-child(4){height:8px;}

/* ── 折叠体 ── */
.fold-body{max-height:0;overflow:hidden;transition:max-height 0.45s cubic-bezier(0.4,0,0.2,1);}
.fold-item.open .fold-body{max-height:3000px;}

/* ── NPC 面板 ── */
.npc-panel{
  position:relative;
  /* 青蓝色调，区别于之前的深海纯蓝 */
  background:linear-gradient(145deg,#040f1e 0%,#071828 40%,#071e30 70%,#040d1a 100%);
  border-radius:0 0 18px 18px;width:100%;
  box-shadow:0 20px 50px rgba(0,8,20,0.8),inset 0 0 50px rgba(60,180,240,0.04);
  border:1px solid rgba(80,200,240,0.14);border-top:none;overflow:hidden;
}
.npc-glimmer{
  position:absolute;inset:0;pointer-events:none;z-index:1;
  background-image:
    radial-gradient(circle at 30% 20%,rgba(60,180,240,0.05) 0%,transparent 40%),
    radial-gradient(circle at 70% 80%,rgba(80,210,255,0.04) 0%,transparent 50%);
  animation:npc-wave 8s infinite alternate ease-in-out;
}
.npc-star{position:absolute;border-radius:50%;background:#d0f0ff;box-shadow:0 0 6px rgba(150,230,255,0.9);animation:npc-twinkle 3s ease-in-out infinite;}
.npc-glow{text-shadow:0 0 8px rgba(100,220,255,0.5),0 0 16px rgba(60,180,240,0.28);}
.npc-content{position:relative;z-index:2;padding:28px 22px 32px;display:flex;flex-direction:column;gap:18px;}

/* 头部 */
.npc-header{display:flex;align-items:center;gap:18px;padding-bottom:14px;border-bottom:1px solid rgba(80,200,240,0.18);}
.npc-avatar{
  width:68px;height:68px;border-radius:50%;flex-shrink:0;
  border:2px solid rgba(80,210,255,0.35);
  background:radial-gradient(circle,rgba(60,180,240,0.22) 0%,rgba(0,0,0,0.55) 100%);
  display:flex;justify-content:center;align-items:center;
  box-shadow:0 0 18px rgba(60,180,240,0.18);
}
.npc-avatar::after{content:"✧";font-size:22px;color:rgba(180,240,255,0.65);}
.npc-title-box{display:flex;flex-direction:column;gap:4px;}
.npc-name{font-size:22px;letter-spacing:4px;color:#ffffff;font-weight:bold;}
.npc-sub{font-size:11px;color:rgba(100,210,255,0.7);letter-spacing:2px;text-transform:uppercase;}
.npc-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:4px;}
.npc-tag{font-size:10px;background:rgba(60,180,240,0.07);border:1px solid rgba(80,210,255,0.28);padding:2px 8px;border-radius:12px;color:rgba(160,235,255,0.82);letter-spacing:1px;}

/* 核心判词 */
.npc-core{
  font-size:13px;font-style:italic;color:rgba(220,245,255,0.82);
  text-align:center;line-height:1.65;padding:10px 12px;
  background:linear-gradient(90deg,transparent,rgba(60,180,240,0.07),transparent);
  border-radius:6px;border-left:none;
}

/* section */
.npc-section{display:flex;flex-direction:column;gap:10px;}
.npc-sec-title{
  font-size:13px;color:rgba(180,235,255,0.88);letter-spacing:2px;
  display:flex;align-items:center;gap:8px;
}
.npc-sec-title::before{content:"◈";font-size:11px;color:rgba(80,210,255,0.65);}
.npc-card{
  background:rgba(0,0,0,0.22);
  border:1px solid rgba(60,180,240,0.10);
  border-radius:8px;padding:12px 14px;
  font-size:12.5px;color:rgba(160,225,255,0.72);line-height:1.7;
  transition:background 0.28s,border-color 0.28s;
}
.npc-card:hover{background:rgba(60,180,240,0.06);border-color:rgba(80,210,255,0.18);}
.npc-card strong{color:rgba(120,220,255,0.88);font-weight:normal;}
.npc-card em{font-style:italic;color:rgba(180,240,255,0.65);}

/* 数据条 */
.npc-stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;}
