const audio=document.getElementById('bgAudio');
const btn=document.getElementById('musicBtn');
const staticBars=document.getElementById('musicStatic');
const animBars=document.getElementById('musicAnim');
const label=document.getElementById('musicLabel');

function toggleMusic(){
  if(!isPlaying){
    audio.play().then(()=>{
      isPlaying=true;
      btn.classList.add('playing');
      staticBars.style.display='none';
      animBars.style.display='flex';
      label.textContent='播放中';
    }).catch(()=>{});
  } else {
    audio.pause();
    isPlaying=false;
    btn.classList.remove('playing');
    staticBars.style.display='flex';
    animBars.style.display='none';
    label.textContent='音乐';
  }
}

audio.addEventListener('ended',()=>{
  isPlaying=false;
  btn.classList.remove('playing');
  staticBars.style.display='flex';
  animBars.style.display='none';
  label.textContent='音乐';
});
</script>
